import json, sys
from collections import defaultdict, deque

def max_window_counts(data: dict) -> dict:
    w = int(data['window_seconds'])
    events = sorted(data.get('events', []), key=lambda x: int(x['timestamp']))
    windows: dict[str, deque[int]] = defaultdict(deque)
    peaks: dict[str, int] = defaultdict(int)
    for ev in events:
        svc, ts = ev['service'], int(ev['timestamp'])
        q = windows[svc]
        q.append(ts)
        while q and (ts - q[0]) >= w:
            q.popleft()
        if len(q) > peaks[svc]:
            peaks[svc] = len(q)
    return {'max_events_per_service': dict(sorted(peaks.items()))}
